<?php
require_once __DIR__ . '/includes/functions.php';
$query = strtolower(trim((string)($_GET['u'] ?? '')));
$stats = load_json_data('global_stats.json');
$badges = load_json_data('badges.json');
$record = null; $userId = '';
if ($query !== '') {
    if (isset($stats[$query]) && is_array($stats[$query])) { $userId=$query; $record=$stats[$query]; }
    else foreach ($stats as $id=>$candidate) {
        if (!is_array($candidate)) continue;
        if (strtolower((string)($candidate['username']??'')) === $query || strtolower((string)($candidate['display_name']??'')) === $query) { $userId=(string)$id; $record=$candidate; break; }
    }
}
$leaders=[];
if ($query==='') {
    foreach($stats as $id=>$candidate) if(is_array($candidate)) $leaders[]=['id'=>(string)$id]+$candidate;
    usort($leaders,fn($a,$b)=>(int)($b['wins']??0)<=>(int)($a['wins']??0));
    $leaders=array_slice($leaders,0,25);
}
if ($query!=='' && !$record) { http_response_code(404); }
function rank_name(int $wins): string { return match(true){$wins>=500=>'Celestial',$wins>=250=>'Godlike',$wins>=100=>'Activity Legend',$wins>=50=>'Activity Master',$wins>=25=>'Elite Member',$wins>=10=>'Hyper Active',default=>'Newcomer'}; }
function safe_profile_url(mixed $value): string { $url=trim((string)$value); $scheme=strtolower((string)parse_url($url, PHP_URL_SCHEME)); return filter_var($url, FILTER_VALIDATE_URL) && in_array($scheme, ['http','https'], true) ? $url : ''; }
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($record ? (($record['display_name']??$record['username']??'Member').' — Rallybit') : ($query===''?'Community profiles — Rallybit':'Profile not found — Rallybit'))?></title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="/dashboard/style.css?v=6.2"><link rel="icon" href="/favicon.ico" sizes="any"><link rel="icon" type="image/png" sizes="32x32" href="/assets/brand/rallybit-icon-32.png"><link rel="icon" type="image/png" sizes="192x192" href="/assets/brand/rallybit-icon-192.png"><link rel="apple-touch-icon" href="/assets/brand/apple-touch-icon.png"></head><body class="public-dashboard-page"><main class="dash-main public-main"><header class="public-topbar"><a class="public-brand" href="/index.html"><img src="/assets/brand/rallybit-icon.png" alt=""><span>Rallybit</span></a><a class="button secondary" href="/dashboard/"><i class="bi bi-grid" aria-hidden="true"></i> Open dashboard</a></header><?php if($query===''):?><section class="panel"><div class="panel-heading"><span><i class="bi bi-search" aria-hidden="true"></i></span><div><h2>Community profiles</h2><p>Search by Discord username or user ID.</p></div></div><form method="get" action="/dashboard/profile.php" class="field-grid"><label>Find a member<input name="u" required placeholder="Username or Discord ID"></label><div style="align-self:end;margin-bottom:16px"><button class="button primary" type="submit">Search</button></div></form></section><section class="panel" style="margin-top:18px"><div class="section-title"><div><h2>Top participants</h2><p>Ranked by activity-check wins.</p></div></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Member</th><th>Wins</th><th>Check-ins</th><th>Rank</th></tr></thead><tbody><?php foreach($leaders as $member):?><tr><td><a href="/dashboard/profile.php?u=<?=urlencode((string)$member['id'])?>"><?=htmlspecialchars((string)($member['display_name']??$member['username']??'Member'))?></a></td><td><?=number_format((int)($member['wins']??0))?></td><td><?=number_format((int)($member['checkins']??0))?></td><td><?=htmlspecialchars(rank_name((int)($member['wins']??0)))?></td></tr><?php endforeach;?></tbody></table></div></section><?php elseif(!$record):?><section class="empty-panel"><h3>Profile not found</h3><p>No Rallybit activity profile matches that search.</p><a class="button secondary" href="/dashboard/profile.php" style="margin-top:16px">Search again</a></section><?php else:$wins=(int)($record['wins']??0);$checkins=(int)($record['checkins']??0);$avatar=$record['avatar_url']??('https://cdn.discordapp.com/embed/avatars/'.(crc32($userId)%6).'.png');$userBadges=is_array($badges[$userId]??null)?$badges[$userId]:[];?><section class="profile-card"><div class="profile-head"><img src="<?=htmlspecialchars((string)$avatar)?>" alt=""><div><span class="kicker"><?=htmlspecialchars(rank_name($wins))?></span><h2><?=htmlspecialchars((string)($record['display_name']??$record['username']??'Member'))?></h2><p>@<?=htmlspecialchars((string)($record['username']??'member'))?></p></div></div><?php if(!empty($record['bio'])):?><p style="color:var(--muted);line-height:1.7"><?=htmlspecialchars((string)$record['bio'])?></p><?php endif;?><div class="summary-row" style="margin:25px 0"><div class="summary-card"><span>Wins</span><strong><?=number_format($wins)?></strong><small>activity-check victories</small></div><div class="summary-card"><span>Check-ins</span><strong><?=number_format($checkins)?></strong><small>recorded participation</small></div><div class="summary-card"><span>Badges</span><strong><?=count($userBadges)?></strong><small>community achievements</small></div></div><?php $profileUrl=safe_profile_url($record['website']??'');if($profileUrl!==''):?><a class="button secondary" rel="noopener noreferrer" target="_blank" href="<?=htmlspecialchars($profileUrl)?>">Visit website</a><?php endif;?></section><?php endif;?></main></body></html>
